actualRule.text:
def(
    "삼각비의 활용",
    "04",
    "일반 삼각형의 변의 길이 구하기 두 변의 길이와 그 끼인각의 크기를 아는 경우",
    SEC.활용,
    "응용",
    (rng) => {
      // $[\overline{AB}$의 계수·근호, $\overline{BC}$, $\angle B$, $\overline{BH}$,
      //  $\overline{AH}$의 계수·근호, $\overline{HC}$, $\overline{AC}]$ —
      // 전부 수선의 발 $H$ 로 실제 계산해 둔 값이라 답이 정수다.
      const [abC, abR, bc, ang, bh, ahC, ahR, hc, ac] = pick(rng, [
        [8, 1, 5, 60, 4, 4, 3, 1, 7],
        [8, 1, 15, 60, 4, 4, 3, 11, 13],
        [16, 1, 21, 60, 8, 8, 3, 13, 19],
        [6, 1, 16, 60, 3, 3, 3, 13, 14],
        [10, 1, 16, 60, 5, 5, 3, 11, 14],
        [24, 1, 35, 60, 12, 12, 3, 23, 31],
        [8, 1, 7, 120, 4, 4, 3, 11, 13],
        [16, 1, 5, 120, 8, 8, 3, 13, 19],
        [6, 1, 10, 120, 3, 3, 3, 13, 14],
        [10, 1, 6, 120, 5, 5, 3, 11, 14],
        [24, 1, 11, 120, 12, 12, 3, 23, 31],
        [3, 2, 7, 45, 3, 3, 1, 4, 5],
        [6, 2, 14, 45, 6, 6, 1, 8, 10],
        [5, 2, 17, 45, 5, 5, 1, 12, 13],
        [12, 2, 17, 45, 12, 12, 1, 5, 13],
        [5, 2, 7, 135, 5, 5, 1, 12, 13],
        [8, 2, 7, 135, 8, 8, 1, 15, 17],
        [7, 2, 17, 135, 7, 7, 1, 24, 25],
      ] as const);
      const abText = surdText(surd(abC, abR, 1));
      const ahText = surdText(surd(ahC, ahR, 1));
      const outer = ang > 90 ? 180 - ang : ang;
      const where =
        ang > 90
          ? `꼭짓점 $A$에서 $\\overline{BC}$의 연장선에 내린 수선의 발을 $H$라 하면 $\\angle ABH=${outer}^\\circ$이므로`
          : `꼭짓점 $A$에서 $\\overline{BC}$에 내린 수선의 발을 $H$라 하면`;
      return {
        content: `삼각형 $ABC$에서 $\\overline{AB}=${cm(abText)}$, $\\overline{BC}=${cm(bc)}$, $\\angle B=${ang}^\\circ$일 때, $\\overline{AC}$의 길이를 구하시오.`,
        answer: `$${cm(ac)}$`,
        solution: `${where} $\\overline{BH}=${abText}\\times\\cos ${outer}^\\circ=${bh}\\,(\\mathrm{cm})$, $\\overline{AH}=${abText}\\times\\sin ${outer}^\\circ=${ahText}\\,(\\mathrm{cm})$이다.\n$\\overline{HC}=${hc}\\,\\mathrm{cm}$이므로 직각삼각형 $AHC$에서 $\\overline{AC}=\\sqrt{(${ahText})^2+${hc}^2}=${ac}\\,(\\mathrm{cm})$이다.`,
        facts: { abC, abR, bc, ang, bh, hc, ac },
        // 원장님 지적 2026-08-25 — `J30503-A04-002` 는 발문이 $\overline{AB}$·
        // $\overline{BC}$ 를 둘 다 말하는데 그림엔 `6 cm` **하나뿐**이었다.
        // 「받은 치수를 다 적는다」는 09 §4-20 이 이미 정한 규칙이다.
        figureSpec: figTwoSides({
          ab: abC * Math.sqrt(abR),
          bc,
          angB: ang,
          dims: { AB: dimCm(abText), BC: dimCm(bc) },
        }),
      };
    },
  ),
